def solve(base, variant):
    if not base or len(base)!=len(variant) or any(type(x) is not bool for x in base+variant):
        raise ValueError('paired booleans required')
    wins=sum(not b and v for b,v in zip(base,variant))
    losses=sum(b and not v for b,v in zip(base,variant))
    return dict(wins=wins,losses=losses,ties=len(base)-wins-losses,delta=(wins-losses)/len(base))
